function validate([coordinate1, coordinate2]) {
  for (const square of [coordinate1, coordinate2]) {
    if (typeof square !== 'string' || !/^[a-h][1-8]$/.test(square)) return 'Each coordinate is a letter from a to h followed by a digit from 1 to 8, like "e4".';
  }
  return null;
}

