function checkTwoChessboards(coordinate1, coordinate2) {
  const color = (square) => {
    const column = square.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
    const row = Number(square[1]);
    return (column + row) % 2;
  };
  const first = color(coordinate1);
  const second = color(coordinate2);
  return first === second;
}

