function checkTwoChessboards(coordinate1, coordinate2) {
  // Paint the board outwards from a1: each square gets the opposite color of the neighbour it was reached from.
  const files = 'abcdefgh';
  const painted = new Map([['a1', 'black']]);
  const queue = [[0, 1]];
  while (queue.length) {
    const [f, r] = queue.shift();
    const here = painted.get(files[f] + r);
    for (const [df, dr] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      const nf = f + df, nr = r + dr;
      if (nf < 0 || nf > 7 || nr < 1 || nr > 8) continue;
      const name = files[nf] + nr;
      if (!painted.has(name)) {
        painted.set(name, here === 'black' ? 'white' : 'black');
        queue.push([nf, nr]);
      }
    }
  }
  return painted.get(coordinate1) === painted.get(coordinate2);
}

